import * as THREE from 'three';
export class Effects {
 constructor(scene,world){this.scene=scene;this.world=world;this.particles=[];this.tracers=[];this.decals=[];this.casings=[];this.maxParticles=320;this.geo=new THREE.SphereGeometry(.022,4,3);this.boxGeo=new THREE.BoxGeometry(.016,.016,.047);this.mat=new THREE.MeshBasicMaterial({color:0xffffff});this.pool=new THREE.InstancedMesh(this.geo,this.mat,this.maxParticles);this.pool.instanceMatrix.setUsage(THREE.DynamicDrawUsage);this.pool.frustumCulled=false;this.pool.count=0;scene.add(this.pool);this.casingsMesh=new THREE.InstancedMesh(this.boxGeo,new THREE.MeshStandardMaterial({color:0xbda26b,metalness:.72,roughness:.35}),64);this.casingsMesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);this.casingsMesh.count=0;this.casingsMesh.frustumCulled=false;scene.add(this.casingsMesh);this.dummy=new THREE.Object3D();this.color=new THREE.Color();this.tracerMaterial=new THREE.LineBasicMaterial({color:0xffe5b2,transparent:true,opacity:.85,depthWrite:false});this.holeTexture=this.makeHole();this.decalMat=new THREE.MeshBasicMaterial({map:this.holeTexture,transparent:true,depthWrite:false,polygonOffset:true,polygonOffsetFactor:-2});this.decalGeo=new THREE.PlaneGeometry(.13,.13);}
 makeHole(){const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d');const g=x.createRadialGradient(32,32,1,32,32,30);g.addColorStop(0,'rgba(0,0,0,.95)');g.addColorStop(.24,'rgba(8,8,7,.9)');g.addColorStop(.4,'rgba(32,28,22,.58)');g.addColorStop(.55,'rgba(10,9,8,.7)');g.addColorStop(1,'rgba(0,0,0,0)');x.fillStyle=g;x.fillRect(0,0,64,64);x.strokeStyle='rgba(0,0,0,.5)';for(let i=0;i<7;i++){const a=i*.9;x.beginPath();x.moveTo(32+Math.cos(a)*9,32+Math.sin(a)*9);x.lineTo(32+Math.cos(a)*25,32+Math.sin(a)*25);x.stroke();}return new THREE.CanvasTexture(c);}
 particle(pos,vel,life,color,size=.7,gravity=12){if(this.particles.length>=this.maxParticles)this.particles.shift();this.particles.push({p:pos.clone(),v:vel,life,max:life,color,size,gravity});}
 impact(hit,dir){const metal=hit.surface==='metal';this.hole(hit.point,hit.normal);for(let i=0;i<(metal?9:6);i++){const v=hit.normal.clone().multiplyScalar(1+Math.random()*3);v.x+=(Math.random()-.5)*3;v.y+=Math.random()*2;v.z+=(Math.random()-.5)*3;this.particle(hit.point,v,.15+Math.random()*.3,metal?0xffc06d:hit.surface==='sand'?0xcbb48d:0xa09b8e,metal?.7:2.8);}}
 hit(pos,dir,head=false){for(let i=0;i<6;i++){const v=dir.clone().multiplyScalar(1+Math.random()*2);v.x+=(Math.random()-.5)*2;v.y+=Math.random()*2;v.z+=(Math.random()-.5)*2;this.particle(pos,v,.17+Math.random()*.2,head?0xffb16b:0x9f4640,1.6);}}
 hole(point,normal){if(this.decals.length>=80){const d=this.decals.shift();this.scene.remove(d);}const mesh=new THREE.Mesh(this.decalGeo,this.decalMat);mesh.position.copy(point).addScaledVector(normal,.012);mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0,0,1),normal);mesh.rotateZ(Math.random()*Math.PI*2);this.scene.add(mesh);this.decals.push(mesh);}
 tracer(from,to,color=0xffd999){if(this.tracers.length>40){const t=this.tracers.shift();this.scene.remove(t.line);t.line.geometry.dispose();t.line.material.dispose();}const g=new THREE.BufferGeometry().setFromPoints([from,to]),m=this.tracerMaterial.clone();m.color.set(color);const line=new THREE.Line(g,m);line.frustumCulled=false;this.scene.add(line);this.tracers.push({line,life:.065});}
 casing(pos,yaw){if(this.casings.length>=64)this.casings.shift();this.casings.push({p:pos.clone(),v:new THREE.Vector3(Math.cos(yaw)*2+(Math.random()-.5),2+Math.random(),-Math.sin(yaw)*2),life:3.5,r:Math.random()*6});}
 explosion(pos){for(let i=0;i<52;i++){const a=Math.random()*Math.PI*2,s=2+Math.random()*8;this.particle(pos,new THREE.Vector3(Math.cos(a)*s,Math.random()*9,Math.sin(a)*s),.3+Math.random()*.9,i%3===0?0x2b2925:0xffb44b,4+Math.random()*10,10);}}
 update(dt){let n=0;for(let i=this.particles.length-1;i>=0;i--){const p=this.particles[i];p.life-=dt;if(p.life<=0){this.particles.splice(i,1);continue;}p.v.y-=p.gravity*dt;p.p.addScaledVector(p.v,dt);const f=this.world.groundHeight(p.p.x,p.p.z,p.p.y+.2,0);if(p.p.y<f+.03){p.p.y=f+.03;p.v.y=Math.abs(p.v.y)*.2;p.v.multiplyScalar(.7);}this.dummy.position.copy(p.p);this.dummy.scale.setScalar(p.size*Math.min(1,p.life*6));this.dummy.updateMatrix();this.pool.setMatrixAt(n,this.dummy.matrix);this.pool.setColorAt(n,this.color.set(p.color));n++;}this.pool.count=n;this.pool.instanceMatrix.needsUpdate=true;if(this.pool.instanceColor)this.pool.instanceColor.needsUpdate=true;
  for(let i=this.tracers.length-1;i>=0;i--){const t=this.tracers[i];t.life-=dt;t.line.material.opacity=Math.max(0,t.life/.065)*.8;if(t.life<=0){this.scene.remove(t.line);t.line.geometry.dispose();t.line.material.dispose();this.tracers.splice(i,1);}}
  n=0;for(let i=this.casings.length-1;i>=0;i--){const c=this.casings[i];c.life-=dt;if(c.life<0){this.casings.splice(i,1);continue;}c.v.y-=18*dt;c.p.addScaledVector(c.v,dt);const floor=this.world.groundHeight(c.p.x,c.p.z,c.p.y+.3,0);if(c.p.y<floor+.018){c.p.y=floor+.018;c.v.y=Math.abs(c.v.y)*.35;c.v.x*=.7;c.v.z*=.7;}c.r+=dt*9;this.dummy.position.copy(c.p);this.dummy.rotation.set(c.r,c.r*.4,c.r*.2);this.dummy.scale.setScalar(1);this.dummy.updateMatrix();this.casingsMesh.setMatrixAt(n++,this.dummy.matrix);}this.casingsMesh.count=n;this.casingsMesh.instanceMatrix.needsUpdate=true;}
 dispose(){for(const t of this.tracers){this.scene.remove(t.line);t.line.geometry.dispose();t.line.material.dispose();}for(const d of this.decals)this.scene.remove(d);this.scene.remove(this.pool,this.casingsMesh);this.geo.dispose();this.mat.dispose();this.boxGeo.dispose();this.casingsMesh.material.dispose();this.holeTexture.dispose();this.decalGeo.dispose();this.decalMat.dispose();this.tracerMaterial.dispose();}
}
